<?php
namespace App\Filament\Resources\Reviews;
use App\Filament\Resources\Concerns\AdminResource; use App\Filament\Resources\Reviews\Pages\ManageReviews; use App\Models\Review;
use BackedEnum; use Filament\Actions\EditAction; use Filament\Forms\Components\Select; use Filament\Schemas\Schema; use Filament\Support\Icons\Heroicon; use Filament\Tables\Columns\TextColumn; use Filament\Tables\Filters\SelectFilter; use Filament\Tables\Table; use Illuminate\Database\Eloquent\Builder;
class ReviewResource extends AdminResource { protected static ?string $model=Review::class; protected static string $viewPermission='reviews.moderate'; protected static ?string $managePermission='reviews.moderate'; protected static string|BackedEnum|null $navigationIcon=Heroicon::OutlinedChatBubbleBottomCenterText; protected static ?string $navigationLabel='Đánh giá'; protected static string|\UnitEnum|null $navigationGroup='Khách hàng & Hậu mãi'; protected static ?int $navigationSort=20; private const STATUSES=['pending'=>'Chờ duyệt','approved'=>'Đã duyệt','rejected'=>'Từ chối']; public static function form(Schema $s):Schema{return $s->components([Select::make('status')->label('Trạng thái')->options(self::STATUSES)->required()]);}public static function table(Table $t):Table{return $t->defaultSort('created_at','desc')->columns([TextColumn::make('product_id')->label('ID sản phẩm'),TextColumn::make('user_id')->label('ID khách'),TextColumn::make('rating')->label('Sao')->numeric(),TextColumn::make('title')->label('Tiêu đề')->limit(35),TextColumn::make('body')->label('Nội dung')->limit(55),TextColumn::make('status')->label('Trạng thái')->badge()->formatStateUsing(fn($s)=>self::STATUSES[$s])])->filters([SelectFilter::make('status')->options(self::STATUSES)])->recordActions([EditAction::make()->label('Duyệt/Sửa')]);}public static function canCreate():bool{return false;}public static function canDelete(\Illuminate\Database\Eloquent\Model $r):bool{return false;}public static function getPages():array{return ['index'=>ManageReviews::route('/')];}}
